def main():
    seen, rows = set(), []
    for en, fa in FA:
        if en in seen:
            continue
        seen.add(en)
        rows.append((en, fa))
    rows.sort(key=lambda r: -len(r[0]))                 # longest first: whole sentences before their words
    esc = lambda t: t.replace("\\", "\\\\").replace('"', '\\"')
    out = ['//+------------------------------------------------------------------+',
           '//| RM_Lang.mqh - Persian text of the panel (2.80); written by        |',
           '//| tools/make_lang.py (edit the table there). Pure text: no orders.   |',
           '//+------------------------------------------------------------------+',
           '#define LG_N %d' % len(rows),
           'string LgEn[LG_N] =',
           '  {']
    out += ['   "%s",' % esc(en) for en, _ in rows[:-1]] + ['   "%s"' % esc(rows[-1][0]), '  };', 'string LgFa[LG_N] =', '  {']
    out += ['   "%s",' % esc(fa) for _, fa in rows[:-1]] + ['   "%s"' % esc(rows[-1][1]), '  };', '']
    out += [open(os.path.join(os.path.dirname(__file__), "lang_engine.mqh"), encoding="utf-8").read()]
    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "MQL5", "Experts", "SlotRiskManager", "RM_Lang.mqh")
    open(path, "w", encoding="utf-8").write("\n".join(out))
    print(len(rows), "phrases ->", path)


if __name__ == "__main__":
    main()
